def fill_steps(apps, schema_editor):
    """Each Soluzioni index page gets the steps in its language, on the page
    and on its current revisions (the CMS editor opens the latest revision)."""
    Index = apps.get_model("solutions", "SolutionsIndexPage")
    Revision = apps.get_model("wagtailcore", "Revision")
    for page in Index.objects.all():
        language = (page.locale.language_code if page.locale_id else "it")[:2]
        heading, steps = STEPS.get(language, STEPS["it"])
        raw = json.dumps([
            {"type": "step", "value": {"title": title, "text": text}, "id": str(uuid.uuid4())}
            for title, text in steps
        ])
        if not page.process_steps:
            page.process_heading = heading
            page.process_steps = raw
            page.save(update_fields=["process_heading", "process_steps"])
        for revision_id in {page.latest_revision_id, page.live_revision_id} - {None}:
            revision = Revision.objects.filter(id=revision_id).first()
            if revision is None or not isinstance(revision.content, dict):
                continue
            if revision.content.get("process_steps") in (None, "", "[]"):
                content = dict(revision.content)
                content["process_heading"] = heading
                content["process_steps"] = raw
                revision.content = content
                revision.save(update_fields=["content"])


